def now(): return datetime.now(timezone.utc).isoformat()
def today(): return datetime.now(JST).date().isoformat()
def norm(value): return unicodedata.normalize('NFKC', str(value or '')).strip()
def compact(value): return re.sub(r'\s+', '', norm(value))
def region_of(address):
    a = compact(address).removeprefix('東京都')
    return next((r for r in REGIONS if a.startswith(r)), '')
def digest(value): return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
def safe_json(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')
def valid_http_url(value):
    try:
        p = urllib.parse.urlsplit(value)
        return value if p.scheme in ('http','https') and p.hostname and not p.username and not p.password else ''
    except (ValueError, TypeError): return ''

class DatabaseError(RuntimeError): pass
class CollectionError(RuntimeError): pass
class Stopped(Exception): pass

def config_from_environment():
    return {'url':os.environ.get('SUPABASE_URL',''), 'secret_key':os.environ.get('SUPABASE_SECRET_KEY') or os.environ.get('SUPABASE_SERVICE_ROLE_KEY','')}

def settings():
    c = config_from_environment()
    try:
        v = st.secrets.get('supabase',{})
        c['url'] = c['url'] or v.get('url','') or st.secrets.get('SUPABASE_URL','')
        c['secret_key'] = c['secret_key'] or v.get('secret_key','') or v.get('service_role_key','') or st.secrets.get('SUPABASE_SECRET_KEY','') or st.secrets.get('SUPABASE_SERVICE_ROLE_KEY','')
    except (FileNotFoundError, st.errors.StreamlitSecretNotFoundError): pass
    return c

class SupabaseStore:
    def __init__(self,url,secret_key,*,opener=None):
        p = urllib.parse.urlsplit(url.strip())
        if p.scheme!='https' or not p.hostname or p.username or p.password or p.query or p.fragment or p.path not in ('','/'):
            raise DatabaseError('SUPABASE_URLにはHTTPSのプロジェクトURLを設定してください。')
        if not secret_key or secret_key.startswith('sb_publishable_'): raise DatabaseError('サーバー用キーを設定してください。')
        self.url=url.strip().rstrip('/'); self._headers={'apikey':secret_key,'Content-Type':'application/json'}
        if secret_key.count('.')==2:
            try:
                raw=secret_key.split('.')[1]; role=json.loads(base64.urlsafe_b64decode(raw+'='*(-len(raw)%4))).get('role')
                if role!='service_role': raise DatabaseError('anonキーではなくサーバー用キーを設定してください。')
            except (ValueError,TypeError,UnicodeError,AttributeError): raise DatabaseError('Supabaseキーの形式を確認してください。') from None
            self._headers['Authorization']='Bearer '+secret_key
        self._opener=opener or urllib.request.urlopen
    def _request(self,path,*,method='GET',body=None,query=None,extra_headers=None):
        endpoint=self.url+'/rest/v1/'+path
        if query: endpoint+='?'+urllib.parse.urlencode(query)
        req=urllib.request.Request(endpoint,data=None if body is None else json.dumps(body,ensure_ascii=False).encode(),headers={**self._headers,**(extra_headers or {})},method=method)
        try:
            with self._opener(req,timeout=40,context=ssl.create_default_context()) as r: b=r.read()
            return json.loads(b) if b else None
        except urllib.error.HTTPError as e:
            messages={400:'保存データまたはSQLの形式を確認してください。',401:'Supabase接続キーを確認してください。',403:'薬局テーブル・関数へのアクセス権を確認してください。',404:'setup.sqlの実行とData APIの設定を確認してください。',409:'保存内容または同時実行状態を確認してください。'}
            error=DatabaseError(messages.get(e.code,f'Supabaseとの通信でHTTP {e.code}が発生しました。'));error.http_status=e.code
            raise error from None
        except (urllib.error.URLError,TimeoutError,OSError,ValueError): raise DatabaseError('Supabaseとの通信に失敗しました。保存完了とは扱わず停止します。') from None
    def all_rows(self,table,order,filters=None):
        if not re.fullmatch(r'(shinagawa|pharmacy)_[a-z_]+',table): raise ValueError('Unexpected table')
        rows=[]; offset=0
        while True:
            q={'select':'*','order':order,'limit':PAGE_SIZE,'offset':offset,**(filters or {})}
            page=self._request(table,query=q)
            if not isinstance(page,list): raise DatabaseError('Supabaseの応答形式が不正です。')
            rows.extend(page)
            if not page: return rows
            offset+=len(page)
    def read_dataset(self):
        ps=self.all_rows(PREFIX+'pharmacies','code.asc')
        rs=self.all_rows(PREFIX+'fee_registrations','pharmacy_code.asc,fee_name.asc')
        ss=self.all_rows(PREFIX+'stations','name.asc')
        rates=self.all_rows(PREFIX+'fee_rates','fee_key.asc')
        ms=self.all_rows(PREFIX+'dataset_info','id.asc')
        by={}
        for r in rs: by.setdefault(r['pharmacy_code'],[]).append({'name':r['fee_name'],'abbr':r['abbreviation'],'start':r['start_label']})
        pharmacies=[]
        for r in ps:
            item=copy.deepcopy(r['payload'])
            item.update(code=r['code'],name=r['name'],address=r['address'],lat=r['latitude'],lon=r['longitude'],registrations=by.get(r['code'],[]),snapshotDate=str(r['snapshot_date']))
            item['region']=region_of(item['address']); pharmacies.append(item)
        stations=[{'name':r['name'],'lat':r['latitude'],'lon':r['longitude'],'lines':r['lines'],'major':r['major']} for r in ss]
        metadata=next((r['metadata'] for r in ms if r['id']=='current'),{})
        app_rates={'basic':{},'regional':{}}
        for r in rates:
            if r['category'] in ('basic','regional'): app_rates[r['category']][r['fee_key']]=float(r['points'])
            else: app_rates[r['category']]=float(r['points'])
        return {'pharmacies':pharmacies,'stations':stations,'rates':app_rates,'metadata':metadata,'rateRows':rates}
    def job(self):
        rows=self._request('pharmacy_update_jobs',query={'id':'eq.current','select':'*'})
        return rows[0] if rows else None
    def action(self,action,owner='',patch=None):
        return self._request('rpc/pharmacy_job_action',method='POST',body={'action':action,'owner':owner,'patch':patch or {}})
    def commit(self,owner,items,state,metadata,region_done='',source_codes=None,stations=None):
        return self._request('rpc/pharmacy_commit_batch',method='POST',body={'owner':owner,'items':items,'next_state':state,'source_meta':metadata,'region_done':region_done,'source_codes':source_codes or [],'station_items':stations or []})
    def events(self):
        return self._request('pharmacy_update_events',query={'select':'*','order':'created_at.desc','limit':200})
    def region_status(self): return self.all_rows('pharmacy_region_status','region.asc')
    def save_rates(self,rows):
        return self._request('rpc/pharmacy_save_rates',method='POST',body={'items':rows})

class LinkParser(HTMLParser):
    def __init__(self): super().__init__(); self.links=[]
    def handle_starttag(self,tag,attrs):
        if tag=='a':
            href=dict(attrs).get('href','')
            if href: self.links.append(href)

class Web:
    """公開資料専用。認証キーは一切渡さない。"""
    def __init__(self,stop=None): self.stop=stop or threading.Event(); self.last={}
    def check(self):
        if self.stop.is_set(): raise Stopped()
    def get(self,url,limit=35_000_000):
        self.check(); p=urllib.parse.urlsplit(url)
        allowed={'kouseikyoku.mhlw.go.jp','msearch.gsi.go.jp','express.heartrails.com'}
        if p.scheme!='https' or p.hostname not in allowed or p.username or p.password: raise CollectionError('取得先URLを確認してください。')
        wait=max(0,.7-(time.monotonic()-self.last.get(p.hostname,0)))
        if self.stop.wait(wait): raise Stopped()
        self.last[p.hostname]=time.monotonic()
        for attempt in range(3):
            self.check()
            try:
                req=urllib.request.Request(url,headers={'User-Agent':'PharmacyComparison/1.0 (public-data updater)'})
                with urllib.request.urlopen(req,timeout=25,context=ssl.create_default_context()) as r:
                    if urllib.parse.urlsplit(r.url).hostname not in allowed: raise CollectionError('未対応の転送先です。')
                    data=r.read(limit+1)
                if len(data)>limit: raise CollectionError('公開資料が処理可能サイズを超えています。')
                return data
            except (urllib.error.URLError,TimeoutError,OSError) as exc:
                audit=getattr(self,'audit',None)
                if audit:audit.record('collection','http.attempt','error' if attempt==2 else 'warning','HTTP '+str(exc.code) if isinstance(exc,urllib.error.HTTPError) else type(exc).__name__,context={'host':p.hostname,'path':p.path,'attempt':attempt+1,'will_retry':attempt<2})
                if attempt==2: raise CollectionError('公開データの取得に失敗しました。取得元の通信状態を確認してください。') from None
                if self.stop.wait(2**attempt): raise Stopped()
    def json(self,url):
        try: return json.loads(self.get(url,5_000_000))
        except (ValueError,UnicodeError): raise CollectionError('公開APIの応答形式を確認してください。') from None

def parse_tokyo_excel(data,check=lambda:None):
    """列名で解析。列位置・年月を固定せず、未知の形式は保存前に停止。"""
    from openpyxl import load_workbook
    book=load_workbook(io.BytesIO(data),read_only=True,data_only=True)
    pharmacies={}; snapshot=None; columns=None
    try:
        for sheet in book:
            columns=None
            for n,row in enumerate(sheet.values):
                if n%500==0: check()
                vals=[str(x or '') for x in row]
                if not columns:
                    s=norm(' '.join(vals))
                    m=re.search(r'令和\s*(\d+)年\s*(\d+)月\s*(\d+)日\s*現在',s)
                    if m: snapshot=f'{2018+int(m[1]):04d}-{int(m[2]):02d}-{int(m[3]):02d}'
                    if '医療機関番号' in vals and '受理届出名称' in vals:
                        columns={v:i for i,v in enumerate(vals)}
                        required=['都道府県コード','医療機関番号','医療機関名称','医療機関所在地（住所）','電話番号','受理届出名称','受理記号','算定開始年月日']
                        if any(x not in columns for x in required): raise CollectionError('公式Excelの列が変更されています。既存データは保持します。')
                    continue
                def cell(key): return str(row[columns[key]] or '').strip()
                if cell('都道府県コード')!='13': continue
                code=cell('医療機関番号').zfill(7)
                if not re.fullmatch(r'\d{7}',code): raise CollectionError('薬局コードの形式が変更されています。')
                address=cell('医療機関所在地（住所）'); region=region_of(address)
                if not region: continue  # 今回の対象外（町村・島しょ）は取り込まない。
                item=pharmacies.setdefault(code,{'code':code,'name':cell('医療機関名称'),'address':address,'phone':cell('電話番号'),'region':region,'registrations':[]})
                if item['address']!=address: raise CollectionError('同一コードの所在地に矛盾があります。')
                fee=cell('受理届出名称')
                if fee:
                    reg={'name':fee,'abbr':cell('受理記号'),'start':cell('算定開始年月日')}
                    previous=next((x for x in item['registrations'] if x['name']==fee),None)
                    if previous and previous!=reg: raise CollectionError('同一薬局・同一届出に異なる内容があります。')
                    if not previous: item['registrations'].append(reg)
    finally: book.close()
    if not snapshot or not pharmacies: raise CollectionError('公式Excelの基準日または薬局を読み取れません。既存データは保持します。')
    datetime.fromisoformat(snapshot)
    for p in pharmacies.values(): p['registrations'].sort(key=lambda x:x['name'])
    return sorted(pharmacies.values(),key=lambda x:x['code']),snapshot

@st.cache_data(ttl=3600,show_spinner=False)
def decode_official_archive(data):
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        names=[n for n in z.namelist() if n.endswith('.xlsx') and ('東京' in n or re.search(r'(^|/)13',n))]
        if len(names)!=1: raise CollectionError('東京都の薬局Excelを一意に特定できません。')
        info=z.getinfo(names[0])
        if info.file_size>120_000_000: raise CollectionError('公式Excelが処理可能サイズを超えています。')
        return parse_tokyo_excel(z.read(names[0]))

def acquire_source(web):
    page=web.get(GOV,3_000_000).decode('utf-8'); parser=LinkParser(); parser.feed(page)
    links=list(dict.fromkeys(urllib.parse.urljoin(GOV,h) for h in parser.links if re.search(r'shisetsu_yakkyoku[^/]*\.zip(?:\?.*)?$',h)))
    if len(links)!=1: raise CollectionError('公式の薬局Excel ZIPを一意に特定できません。URL変更を確認してください。')
    archive=web.get(links[0]); web.check()
    try: rows,snapshot=decode_official_archive(archive)
    except (zipfile.BadZipFile,KeyError,ValueError,TypeError): raise CollectionError('公式ZIP/Excelの形式を読み取れません。') from None
    return rows,{'pharmacies_as_of':snapshot,'pharmacies_source':GOV,'pharmacies_download':links[0],'source_hash':hashlib.sha256(archive).hexdigest(),'retrieved_on':today(),'locations_source':GSI,'stations_source':'https://express.heartrails.com/api.html','stations_attribution':'HeartRails Express'}

def address_query(address):
    a=compact(address).removeprefix('東京都')
    # 地番より後のビル名を住所検索へ混ぜない。漢数字の丁目を数字化。
    nums={'一':1,'二':2,'三':3,'四':4,'五':5,'六':6,'七':7,'八':8,'九':9,'十':10,'十一':11,'十二':12,'十三':13}
    a=re.sub(r'([一二三四五六七八九十]+)丁目',lambda m:str(nums.get(m[1],m[1]))+'丁目',a)
    a=re.split(r'\d+(?:階|F)',a)[0]
    return '東京都'+a

def geocode(web,address):
    q=address_query(address); region=region_of(address)
    # 町名までの一致を必須にし、自治体の中心などの誤ピンを作らない。
    after=q.removeprefix('東京都').removeprefix(region)
    town=re.split(r'[0-9]',after)[0]
    results=web.json(GSI+'?'+urllib.parse.urlencode({'q':q}))
    if not isinstance(results,list): raise CollectionError('住所検索の応答形式を確認してください。')
    for r in results:
        title=compact(r.get('properties',{}).get('title',''))
        xy=r.get('geometry',{}).get('coordinates',[])
        if region and town and region+town in title and len(xy)==2:
            lon,lat=map(float,xy)
            if 35<=lat<=36.2 and 138.8<=lon<=140:
                return {'lat':lat,'lon':lon,'geocoded':True,'geoLabel':title,'coordinateSource':GSI,'coordinateCheckedOn':today()}
    return {'lat':None,'lon':None,'geocoded':False,'coordinateIssue':'町名と一致する住所候補なし'}

def combine_pharmacy(source,old,meta,web,force=False):
    p=copy.deepcopy(source); p.update(snapshotDate=meta['pharmacies_as_of'],sourceUrl=meta['pharmacies_download'],sourceMissing=False)
    same_address=old and compact(old['address'])==compact(p['address'])
    same_identity=same_address and compact(old.get('name'))==compact(p['name'])
    if same_identity:
        for k in ('website','officialFeesUrl','officialCheckedOn','locationName'):
            if k in old: p[k]=old[k]
    if same_address and old.get('lat') is not None and old.get('lon') is not None and not force:
        for k in ('lat','lon','geocoded','geoLabel','coordinateSource','coordinateCheckedOn'):
            if k in old:p[k]=old[k]
    else:
        try:
            location=geocode(web,p['address'])
            if same_address and old.get('lat') is not None and location.get('lat') is None:
                location.update(lat=old['lat'],lon=old['lon'],geocoded=old.get('geocoded',False),geoLabel=old.get('geoLabel',''),coordinateIssue='再検索で位置を確認できず・同じ住所の保存済み位置を維持')
            p.update(location)
        except CollectionError:
            p.update(lat=old.get('lat') if same_address else None,lon=old.get('lon') if same_address else None,coordinateIssue='住所検索に失敗・次回再試行')
    return p

class StationCollector:
    def __init__(self,web): self.web=web; self.lines=None; self.cache={}; self.issues=[]
    def collect(self,region,pharmacies):
        points=[p for p in pharmacies if p.get('lat') is not None and p.get('lon') is not None]
        if not points: return []
        if self.lines is None:
            response=self.web.json(STATION_API+'?'+urllib.parse.urlencode({'method':'getLines','prefecture':'東京都'})).get('response',{})
            self.lines=response.get('line')
            if not isinstance(self.lines,list) or not self.lines: raise CollectionError('東京都の路線一覧を取得できません。')
        south=min(x['lat'] for x in points)-.015; north=max(x['lat'] for x in points)+.015
        west=min(x['lon'] for x in points)-.02; east=max(x['lon'] for x in points)+.02
        found={}
        for line in self.lines:
            self.web.check()
            if line not in self.cache:
                try:
                    response=self.web.json(STATION_API+'?'+urllib.parse.urlencode({'method':'getStations','line':line,'prefecture':'東京都'})).get('response',{})
                    rows=response.get('station')
                    if not isinstance(rows,list):raise CollectionError('駅一覧を取得できません。')
                    self.cache[line]=rows
                except CollectionError:
                    self.issues.append(line);continue
            for x in self.cache[line]:
                lat=float(x['y']);lon=float(x['x'])
                if not (south<=lat<=north and west<=lon<=east): continue
                # 現行テーブル互換: 同名駅は代表位置を1つにまとめる。
                s=found.setdefault(x['name'],{'name':x['name'],'lat':lat,'lon':lon,'lines':[],'major':False})
                if x['line'] not in s['lines']:s['lines'].append(x['line'])
        for s in found.values(): s['major']=len(s['lines'])>=2
        return list(found.values())

@st.cache_resource
def registry(): return {},threading.RLock()

def registry_key(config): return digest([config['url'],config['secret_key']])

class UpdateWorker:
    def __init__(self,store,*,source_loader=acquire_source,web=None,station_factory=StationCollector):
        self.store=store;self.owner=uuid.uuid4().hex;self.stop=threading.Event();self.done=threading.Event();self.lock=threading.RLock()
        self.web=web or Web(self.stop);self.source_loader=source_loader;self.station_factory=station_factory
        self.message='準備中';self.error='';self.pending=None
        self.thread=threading.Thread(target=self.run,daemon=True,name='pharmacy-update')
    def start(self):self.thread.start()
    def snapshot(self):
        with self.lock:return {'running':self.thread.is_alive(),'message':self.message,'error':self.error,'pending':self.pending}
    def request_stop(self):
        self.stop.set();self.store.action('stop')
    def heartbeat(self):
        while not self.done.wait(20):
            try:
                row=self.store.action('heartbeat',self.owner)
                if not row or row.get('stop_requested'):self.stop.set()
            except DatabaseError:
                self.stop.set()
                with self.lock:self.error='進捗保存先との通信が切れたため停止しました。保存済み地点から再開できます。'
                return
    def check(self):
        if self.stop.is_set():raise Stopped()
    def checkpoint(self,state,status='running'):
        return self.store.action('save',self.owner,{'state':state,'status':status})
    def run(self):
        heartbeat=None;state={}
        try:
            job=self.store.action('claim',self.owner)
            if not job:return
            state=copy.deepcopy(job['state']);heartbeat=threading.Thread(target=self.heartbeat,daemon=True);heartbeat.start()
            rows,meta=self.source_loader(self.web);self.check()
            if state.get('source_hash')!=meta['source_hash']:
                state.update(region_index=0,offset=0,source_hash=meta['source_hash'],source=meta,stats={'processed':0,'new':0,'updated':0,'unchanged':0,'unlocated':0},station_issues=[])
                self.checkpoint(state)
            existing={p['code']:p for p in self.store.read_dataset()['pharmacies']}
            station_collector=self.station_factory(self.web)
            regions=state['regions'];state.setdefault('stats',{'processed':0,'new':0,'updated':0,'unchanged':0,'unlocated':0})
            while state.get('region_index',0)<len(regions):
                self.check();i=state.get('region_index',0);region=regions[i]
                selected=[p for p in rows if p['region']==region]
                if not selected:raise CollectionError(region+'の薬局が0件です。削除せず停止しました。')
                offset=state.get('offset',0)
                if offset>len(selected):raise CollectionError('再開地点が取得データと一致しません。')
                while offset<len(selected):
                    self.check();batch=[]
                    # 5件ずつ原子的に保存。停止時の再取得は最大5件。
                    next_state=copy.deepcopy(state)
                    for source in selected[offset:offset+5]:
                        self.check()
                        with self.lock:self.message=f'{region}｜{offset+len(batch)+1}/{len(selected)}件｜{source["name"]}'
                        p=combine_pharmacy(source,existing.get(source['code']),meta,self.web,state.get('force',False))
                        batch.append(p)
                    next_state['offset']=offset+len(batch)
                    result=self.store.commit(self.owner,batch,next_state,meta)
                    state=result['state'];offset=state['offset']
                    for p in batch:existing[p['code']]=p
                    with self.lock:self.pending=None
                self.check()
                stations=[];station_issue=''
                if state.get('stations',True):
                    with self.lock:self.message=region+'｜周辺の駅情報を更新中'
                    try:
                        stations=station_collector.collect(region,[existing[p['code']] for p in selected])
                        if getattr(station_collector,'issues',[]):station_issue='一部路線の駅情報は再試行待ちです。確認できた駅と保存済み駅を保持しています。'
                    except CollectionError:station_issue='駅情報の取得に失敗。保存済み駅は保持しています。'
                next_state=copy.deepcopy(state);next_state.update(region_index=i+1,offset=0)
                if station_issue:next_state.setdefault('station_issues',[]).append(region)
                result=self.store.commit(self.owner,[],next_state,{**meta,'station_issue':station_issue},region_done=region,source_codes=[p['code'] for p in selected],stations=stations)
                state=result['state']
                with self.lock:self.message=region+'｜保存完了'+('（駅情報は再試行待ち）' if station_issue else '')
            incomplete=bool(state.get('stats',{}).get('unlocated',0) or state.get('station_issues'))
            status='partial' if incomplete else 'completed'
            self.checkpoint(state,status)
            with self.lock:self.message='選択地域の更新が完了しました。'+('未確認の座標・駅情報は更新タブで確認できます。次回の更新で再試行します。' if incomplete else '')
        except Stopped:
            try:
                # DBにある最後の確定進捗を維持。手元の未保存状態を上書きしない。
                job=self.store.job()
                if job and job.get('lease_owner')==self.owner:self.checkpoint(job['state'],'paused')
            except DatabaseError:pass
            with self.lock:self.message='停止しました。保存済み地点から再開できます。'
        except (DatabaseError,CollectionError) as e:
            with self.lock:self.error=str(e);self.message='更新を停止しました。保存済みデータは保持しています。'
            try:
                job=self.store.job()
                if job and job.get('lease_owner')==self.owner:
                    state=job['state'];state['error']=str(e);self.checkpoint(state,'failed')
            except DatabaseError:pass
        except Exception as e:
            with self.lock:self.error='処理に失敗しました（'+type(e).__name__+'）。保存済みデータは保持しています。'
            try:
                job=self.store.job()
                if job and job.get('lease_owner')==self.owner:
                    state=job['state'];state['error']=self.error;self.checkpoint(state,'failed')
            except DatabaseError:pass
        finally:
            self.done.set()
            if heartbeat:heartbeat.join(timeout=1)

def worker_for(config,store,start=False):
    jobs,lock=registry();key=registry_key(config)
    with lock:
        job=jobs.get(key)
        if start and (job is None or not job.thread.is_alive()):
            job=UpdateWorker(store);jobs[key]=job;job.start()
        return job

# ── 作業ログ（画面操作／データ取得を共通形式で記録） ───────────────────────
LOG_SCHEMA = 2
LOG_CATEGORIES = {'ui','collection','database','system'}
LOG_STATUSES = {'started','ok','info','skipped','warning','error','cancelled'}

class WorkLog:
    """SQLiteに先に記録し、既存のSupabaseログテーブルへ非同期で送る。"""
    def __init__(self, config, *, path=None, start=True):
        self.path=str(path or (Path(tempfile.gettempdir())/('pharmacy-worklog-'+digest(config.get('url',''))[:20]+'.sqlite3')))
        self.redactions=tuple(x for x in (config.get('secret_key'),) if x)
        self.lock=threading.RLock();self.local=threading.local();self.sink=None
        self.storage_error='';self.upload_error='';self.last_uploaded_at='';self.stop=threading.Event();self.last_failure=0
        with self.connect() as db:
            db.execute('PRAGMA journal_mode=WAL')
            db.execute('CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY,category TEXT NOT NULL,status TEXT NOT NULL,started_at TEXT NOT NULL,event TEXT NOT NULL,uploaded INTEGER NOT NULL DEFAULT 0)')
            db.execute('CREATE INDEX IF NOT EXISTS log_filter ON events(category,status,started_at)')
        if start:
            self.thread=threading.Thread(target=self.loop,daemon=True,name='pharmacy-log-upload');self.thread.start()
    def connect(self):return sqlite3.connect(self.path,timeout=5)
    def clean(self,value,depth=0):
        if depth>5:return '[省略]'
        if isinstance(value,dict):
            blocked={'password','secret_key','token','apikey','authorization','headers','payload','search','query','input','raw','html'}
            return {str(k)[:64]:self.clean(v,depth+1) for k,v in list(value.items())[:32] if str(k).lower() not in blocked}
        if isinstance(value,(list,tuple)):return [self.clean(x,depth+1) for x in value[:64]]
        if isinstance(value,str):
            for secret in self.redactions:value=value.replace(secret,'[非記録]')
            value=re.sub(r'sb_(?:secret|publishable)_[A-Za-z0-9_-]+','[非記録]',value)
            value=re.sub(r'eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+','[非記録]',value)
            value=re.sub(r'(https?://[^\s?]+)\?[^\s]+',r'\1?[非記録]',value)
            return value[:600]
        if value is None or isinstance(value,(bool,int)):return value
        if isinstance(value,float):return value if math.isfinite(value) else None
        return self.clean(str(value),depth+1)
    def context(self,**values):self.local.context=self.clean(values)
    def record(self,category,action,status='ok',detail='',*,duration_ms=0,started_at=None,context=None,run_id=None,event_id=None,source='server',ended_at=None):
        end=ended_at or now();start=started_at or end
        category=category if category in LOG_CATEGORIES else 'system'
        status=status if isinstance(status,str) and status in LOG_STATUSES else 'info'
        try:duration=max(0,round(float(duration_ms),3))
        except (ValueError,TypeError):duration=0
        if not math.isfinite(duration):duration=0
        ctx={**getattr(self.local,'context',{}),**(context or {})}
        event={'schema_version':LOG_SCHEMA,'event_id':event_id or uuid.uuid4().hex,'run_id':run_id or ctx.pop('run_id',None) or '',
            'category':category,'action':str(action)[:100],'status':status,'status_detail':self.clean(detail),
            'started_at':start,'ended_at':end,'duration_ms':duration,'source':source,'build':BUILD,'context':self.clean(ctx)}
        try:
            with self.lock,self.connect() as db:
                db.execute('INSERT OR IGNORE INTO events VALUES(?,?,?,?,?,0)',(event['event_id'],category,status,start,json.dumps(event,ensure_ascii=False)))
            self.storage_error=''
            return event['event_id']
        except (sqlite3.Error,OSError):
            self.storage_error='作業ログをサーバーの一時保存領域へ書き込めません。ログの保存を確認できていません。'
            return None
    @contextmanager
    def span(self,category,action,context=None):
        began=now();clock=time.perf_counter();result={}
        try:yield result
        except Exception as e:
            status='cancelled' if (isinstance(e,Stopped) or type(e).__name__=='Stopped') else 'error'
            self.record(category,action,status,type(e).__name__+': '+str(e),duration_ms=(time.perf_counter()-clock)*1000,started_at=began,context={**(context or {}),'http_status':getattr(e,'http_status',None)})
            raise
        else:self.record(category,action,result.pop('status','ok'),result.pop('detail','完了'),duration_ms=(time.perf_counter()-clock)*1000,started_at=began,context={**(context or {}),**result})
    def ingest_browser(self,payload,session_id):
        accepted=[]
        if not isinstance(payload,dict):return accepted
        events=payload.get('events',[])
        if not isinstance(events,list):return accepted
        for row in events[:100]:
            if not isinstance(row,dict):continue
            eid=row.get('event_id','');action=row.get('action','')
            if not re.fullmatch(r'[a-zA-Z0-9_-]{8,100}',str(eid)) or not re.fullmatch(r'[a-zA-Z0-9_.:-]{1,100}',str(action)):continue
            ctx=row.get('context',{})
            if not isinstance(ctx,dict):ctx={}
            allowed={'element','control','view','width','height','dpr','count','query_length','checked','zoom','visible','duration_kind','long_task_ms','message','line','column','region','value','pending_count','sample_rate','sequence',
                'render_id','scope','page_id','touch','visibility','document_id','server_session','trace_id','event_type','input_type','mutations','phase_total_ms','outcome','phase','interaction_id','input_delay_ms','processing_ms','presentation_ms','relative_start_ms','host','resource_type','transfer_bytes','ttfb_ms','download_ms','timing_restricted','tile_count','tile_errors','event_timing','longtask','resource_timing','layout_shift','recent_input','hardware_concurrency','device_memory_gb','connection_type','rtt_ms','downlink_mbps','save_data'}
            ctx={k:v for k,v in ctx.items() if k in allowed}
            client_started=row.get('started_at')
            try:
                parsed=datetime.fromisoformat(str(client_started).replace('Z','+00:00'))
                if parsed.tzinfo is None:raise ValueError()
                client_started=parsed.isoformat()
            except (ValueError,TypeError):client_started=None
            try:
                client_duration=max(0,min(86400000,float(row.get('duration_ms',0))))
                if not math.isfinite(client_duration):client_duration=0
            except (TypeError,ValueError):client_duration=0
            client_end=(parsed+timedelta(milliseconds=client_duration)).isoformat() if client_started else None
            status=row.get('status','ok')
            saved=self.record('ui',action,status,row.get('status_detail',''),duration_ms=client_duration,started_at=client_started,ended_at=client_end,
                context=ctx,run_id=session_id,event_id=eid,source='browser')
            if saved:accepted.append(eid)
        return accepted
    def flush_once(self):
        if not self.sink:return 0
        with self.lock,self.connect() as db:
            pending=db.execute('SELECT id,event FROM events WHERE uploaded=0 ORDER BY rowid LIMIT 100').fetchall()
        if not pending:return 0
        events=[json.loads(x[1]) for x in pending]
        batch={'id':'wl_'+digest([x[0] for x in pending]),'run_id':events[0]['run_id'],'stage':'work_log_batch','region':'',
            'details':{'schema_version':LOG_SCHEMA,'events':events}}
        try:self.sink(batch)
        except Exception:
            self.upload_error='Supabaseへのログ保存を確認できません。未送信分を保持し、再送します。'
            if time.monotonic()-self.last_failure>60:
                self.last_failure=time.monotonic();self.record('system','log.upload','error',self.upload_error)
            return 0
        with self.lock,self.connect() as db:db.executemany('UPDATE events SET uploaded=1 WHERE id=?',[(x[0],) for x in pending])
        self.upload_error='';self.last_uploaded_at=now();return len(pending)
    def loop(self):
        while not self.stop.wait(5):
            try:self.flush_once()
            except (sqlite3.Error,OSError):self.storage_error='作業ログの保存領域へアクセスできません。'
    def pending(self):
        with self.lock,self.connect() as db:return db.execute('SELECT count(*) FROM events WHERE uploaded=0').fetchone()[0]
    def read(self,category='all',status='all',days=7):
        where=[];args=[]
        if category!='all':where.append('category=?');args.append(category)
        if status!='all':where.append('status=?');args.append(status)
        if days:where.append('started_at>=?');args.append((datetime.now(timezone.utc)-timedelta(days=days)).isoformat())
        sql='SELECT event FROM events'+(' WHERE '+' AND '.join(where) if where else '')+' ORDER BY started_at,id'
        with self.lock,self.connect() as db:return [json.loads(x[0]) for x in db.execute(sql,args)]
    def restore(self,batches):
        count=0
        with self.lock,self.connect() as db:
            for batch in batches:
                for e in (batch.get('details') or {}).get('events',[]):
                    if not isinstance(e,dict) or not all(k in e for k in ('event_id','category','status','started_at')):continue
                    before=db.total_changes
                    db.execute('INSERT OR IGNORE INTO events VALUES(?,?,?,?,?,1)',(e['event_id'],e['category'],e['status'],e['started_at'],json.dumps(self.clean(e),ensure_ascii=False)))
                    count+=db.total_changes-before
        return count

@st.cache_resource
def work_log(url,secret_key):return WorkLog({'url':url,'secret_key':secret_key})

def trace(audit,category,action,context=None):
    return audit.span(category,action,context) if audit else nullcontext({})

def log_action(action,detail='',context=None,status='ok'):
    audit=st.session_state.get('_work_log')
    if audit:audit.record('ui',action,status,detail,context=context,run_id=st.session_state.get('_log_session',''))

# 計測を本体の通信・更新処理へ接続。ログ失敗を本体へ伝播させない。
_original_db_request = SupabaseStore._request

def _logged_db_request(self,path,**kwargs):
    audit=getattr(self,'audit',None)
    if path=='pharmacy_update_events' and kwargs.get('method')=='POST':return _original_db_request(self,path,**kwargs)
    context={'resource':path,'method':kwargs.get('method','GET')}
    body=kwargs.get('body') or {}
    if path.endswith('pharmacy_job_action'):context['command']=body.get('action','')
    if path.endswith('pharmacy_commit_batch'):context['item_count']=len(body.get('items',[]))
    with trace(audit,'database','request',context) as result:
        value=_original_db_request(self,path,**kwargs)
        if audit and path.endswith('pharmacy_job_action') and body.get('action')=='claim' and isinstance(value,dict):audit.context(run_id=value.get('state',{}).get('run_id',''))
        if isinstance(value,list):result['row_count']=len(value)
        elif isinstance(value,dict):
            for k in ('saved','new','updated','unchanged'):
                if k in value:result[k]=value[k]
        return value
SupabaseStore._request=_logged_db_request

def _persist_work_logs(self,batch):
    return _original_db_request(self,'pharmacy_update_events',method='POST',body=[batch],query={'on_conflict':'id'},extra_headers={'Prefer':'resolution=merge-duplicates'})
SupabaseStore.persist_work_logs=_persist_work_logs

_original_web_get=Web.get

def _logged_web_get(self,url,limit=35_000_000):
    p=urllib.parse.urlsplit(url);audit=getattr(self,'audit',None)
    with trace(audit,'collection','http.fetch',{'host':p.hostname,'path':p.path}) as result:
        data=_original_web_get(self,url,limit);result['bytes']=len(data);return data
Web.get=_logged_web_get

_original_geocode=geocode

def _logged_geocode(web,address):
    with trace(getattr(web,'audit',None),'collection','coordinate.lookup',{'region':region_of(address)}) as result:
        value=_original_geocode(web,address)
        if value.get('lat') is None:result.update(status='warning',detail='町名と一致する位置を確認できず。未確認として保存し、次回再試行。')
        return value
geocode=_logged_geocode

_original_combine=combine_pharmacy

def _logged_combine(source,old,meta,web,force=False):
    audit=getattr(web,'audit',None)
    if audit:audit.context(run_id=getattr(audit.local,'context',{}).get('run_id') or getattr(web,'log_run_id',''),region=source.get('region',''),pharmacy_code=source.get('code',''))
    with trace(audit,'collection','pharmacy.prepare',{'pharmacy_code':source.get('code',''),'region':source.get('region','')}) as result:
        value=_original_combine(source,old,meta,web,force)
        result.update(coordinate_reused=bool(old and not force and compact(old.get('address'))==compact(source.get('address')) and old.get('lat') is not None))
        if value.get('coordinateIssue'):result.update(status='warning',detail=value['coordinateIssue'])
        return value
combine_pharmacy=_logged_combine

_original_station_collect=StationCollector.collect

def _logged_station_collect(self,region,pharmacies):
    with trace(getattr(self.web,'audit',None),'collection','stations.update',{'region':region}) as result:
        stations=_original_station_collect(self,region,pharmacies);result['station_count']=len(stations)
        if self.issues:result.update(status='warning',detail='一部路線の情報が未確認です。',failed_line_count=len(self.issues))
        return stations
StationCollector.collect=_logged_station_collect

_original_worker_run=UpdateWorker.run

def _logged_worker_run(self):
    audit=getattr(self.store,'audit',None);self.web.audit=audit;self.web.log_run_id=self.owner
    if audit:audit.context(run_id=self.owner)
    if audit:audit.record('collection','update.run','started','取得・更新を開始')
    clock=time.perf_counter();began=now()
    loader=self.source_loader
    def logged_source(web):
        with trace(audit,'collection','source.load_and_parse') as result:
            rows,meta=loader(web);result.update(row_count=len(rows),snapshot_date=meta.get('pharmacies_as_of',''),source_hash=meta.get('source_hash',''))
            return rows,meta
    self.source_loader=logged_source
    try:_original_worker_run(self)
    finally:
        self.source_loader=loader
        if audit:
            snap=self.snapshot();status='error' if snap.get('error') else 'cancelled' if self.stop.is_set() else 'skipped' if snap.get('message')=='準備中' else 'ok'
            audit.record('collection','update.run',status,snap.get('error') or snap.get('message',''),duration_ms=(time.perf_counter()-clock)*1000,started_at=began)
            audit.context()
UpdateWorker.run=_logged_worker_run

def performance_report(rows):
    """区間は重複し得るため合算しない。タイムアウトは成功の分位点から除外。"""
    groups={};capabilities=[]
    for e in rows:
        c=e.get('context',{});action=e.get('action','')
        if action=='performance.capabilities':capabilities.append({'session_id':e.get('run_id',''),**c})
        if action not in {'interaction.display','performance.event_timing','render.phase','map.tiles','page.initial_display','component.display','server.render','dataset.load','request','performance.long_task','performance.event_loop'}:continue
        device='mobile' if 0<c.get('width',0)<768 else 'desktop' if c.get('width') else 'server'
        key=(action,str(c.get('element') or c.get('phase') or c.get('resource') or ''),device,c.get('scope','server'))
        g=groups.setdefault(key,{'durations':[],'incomplete':0,'errors':0,'over_500ms':0,'count':0})
        g['count']+=1
        if c.get('outcome') in {'superseded','timeout','hidden','pagehide'} or c.get('visible') is False:g['incomplete']+=1;continue
        if e.get('status')=='error':g['errors']+=1;continue
        n=e.get('duration_ms',0)
        if isinstance(n,(int,float)) and math.isfinite(n):g['durations'].append(max(0,n));g['over_500ms']+=int(n>500)
    result=[]
    for (action,element,device,scope),g in groups.items():
        values=sorted(g.pop('durations'));n=len(values)
        def pct(p):return round(values[max(0,math.ceil(n*p)-1)],2) if n else None
        result.append({'action':action,'element_or_phase':element,'device':device,'scope':scope,**g,'completed_count':n,'p50_ms':pct(.5),'p95_ms':pct(.95),'max_ms':values[-1] if n else None})
    result.sort(key=lambda x:x['p95_ms'] or 0,reverse=True)
    return {'summary':result,'capabilities':capabilities,'interpretation':[
        'interaction.display: イベント開始からDOMが120ms安定し、2フレーム経過するまでの代理指標。実際の画面発光・画像内容の完全表示を保証しません。',
        'アプリのタブ切替・表示地域変更ではサーバーの画面生成マーカー更新も待ちます。計測開始前の初回アクセスから外枠表示までの待ち時間は含みません。',
        'performance.event_timing: 対応ブラウザーのみ。入力待ち・イベント処理・次の描画の内訳。16ms未満は通常記録されず、公式INPスコアではありません。',
        'render.phase: 同期関数の実行区間。親関数・子関数と重複するため足し算しません。',
        'map.tiles: 背景地図の読み込み。初回は監視開始時点からの区間で、ピンと一覧の描画完了とは別です。',
        '幅768px未満をmobileと分類。スマートフォン実機を保証する分類ではありません。',
        'superseded/timeout/hidden/pagehideは未完了として分位点から除外。サンプルが少ないp95は参考値です。',
        'trace_idで同一操作、document_idで同じ比較画面、server_sessionでサーバー処理を照合。クライアント時計とサーバー時計の差があるため時刻差を通信時間と解釈しません。',
        '検索語・住所入力・接続キーは記録しません。端末幅、タッチ対応、通信状況などの診断情報を記録します。',
        'ブラウザーの制限で非対応の項目やクロスオリジン通信の詳細は欠測となります。0を高速と断定しないでください。',
        'ブラウザーログは10秒おきにまとめて送信。サーバー保存前にアプリを強制終了すると最後の操作が未送信となる場合があります。'
    ]}

