    doc=doc.replace('<script>'+UI_JS.replace('</script','<\\/script'),telemetry+'<script>'+UI_JS.replace('</script','<\\/script'),1)
    sig=digest(doc)
    if st.session_state.get('_last_map_document')!=sig:
        st.session_state['_last_map_document']=sig
